  const tbl = [...document.querySelectorAll('.ant-table table')].find(t => [...t.querySelectorAll('th')].some(th => th.innerText.trim().startsWith('Failure reason')));
  const bodyRows = [...tbl.querySelectorAll('tbody tr')].filter(r => !r.classList.contains('ant-table-measure-row'));
  if (!bodyRows.length) return { rows: 0 };
  const headers = [...tbl.querySelectorAll('th')].map(th => th.innerText.trim());
  const idx = headers.indexOf('Failure reason');
  const cell = bodyRows[0].children[idx];
