  inner.textContent = LONG;
  // force layout
  const w = Math.round(cell.getBoundingClientRect().width);
  return {
    bodyRowCount: bodyRows.length,
    declaredColWidth: [...tbl.querySelectorAll('colgroup col')].map(c => c.style.width || '(auto)')[idx],
    renderedCellWidthAfterLongText: w,
    tableWidthAfter: Math.round(tbl.getBoundingClientRect().width),
    ellipsisVisible: inner.scrollWidth > Math.ceil(inner.clientWidth) || cell.scrollWidth > Math.ceil(cell.clientWidth),
    tableLayout: getComputedStyle(tbl).tableLayout,
    tableWidthStyle: tbl.style.width,
  };
}

