import { Tooltip } from 'antd';
import type { ColumnType } from 'antd/es/table';

/**
 * A bounded-width, single-line-ellipsis `ColumnType` for a free-text field
 * that can be arbitrarily long — a provider error string, a failure reason,
 * a message. Without a width + ellipsis, one long unbroken string stretches
 * the whole column (and the table's horizontal scrollbar with it) to fit on
 * one line, which is exactly what made the pipeline-runs "Failure reason"
 * column unusable (#1184).
 *
 * `ellipsis: { showTitle: false }` suppresses antd's own native-`title`
 * hover (plain browser tooltip, no styling) so the custom `Tooltip` below is
 * the only one — antd's documented pattern for a styled hover reveal. The
 * `null`/`undefined` placeholder (`'—'`) renders un-tooltipped: there's
 * nothing to reveal.
 */
export function ellipsisColumn<T>(
  title: string,
  dataIndex: keyof T & string,
  width: number,
): ColumnType<T> {
  return {
    title,
    dataIndex,
    width,
    ellipsis: { showTitle: false },
    render: (value: string | null | undefined) =>
      value === null || value === undefined ? (
        '—'
      ) : (
        <Tooltip title={value}>
          <span>{value}</span>
        </Tooltip>
      ),
  };
}

  {
    title: 'Expectation',
    dataIndex: 'check_id',
    render: (id: string) => (
      <Typography.Text type="secondary" style={{ fontSize: 12 }}>
        {checks.get(id)?.expectation_type ?? '—'}
      </Typography.Text>
    ),
  },
  {
    title: 'Status',
    dataIndex: 'status',
    width: 100,
    render: (s: ResultStatus) => <Tag color={RESULT_STATUS_COLORS[s]}>{s}</Tag>,
  },
  {
    title: 'Metric',
    dataIndex: 'metric_value',
    width: 90,
    render: (v: number | null) => (v === null ? '—' : v),
  },
  {
    // Bounded width + ellipsis (#1207 — #1184's "verified-benign" scope-out
    // didn't hold for every monitor kind: schema_drift's added/removed
    // column lists and comparison's per-column buckets both scale with
    // column count, and ScalarValue's formatScalar JSON.stringifies
    // whatever shape observed_value is, unbounded. `ellipsis: { showTitle:
    // false }` suppresses antd's own native-title hover so the Tooltip
    // below is the only one — same pattern as `ellipsisColumn` (#1184),
    // applied manually here since this column has a custom ScalarValue
    // render rather than a plain string field. ScalarValue's own
    // formatting (monospace, em-dash for null) is reused unchanged in
    // both the cell and the tooltip.
    title: 'Observed',
    dataIndex: 'observed_value',
    width: 220,
    ellipsis: { showTitle: false },
    render: (v: Record<string, unknown> | null) =>
      v === null || v === undefined ? (
        <ScalarValue value={v} />
      ) : (
        <Tooltip title={<ScalarValue value={v} />}>
          <span>
            <ScalarValue value={v} />
          </span>
        </Tooltip>
      ),
  },
];
return (
  <Table
    scroll={{ x: 'max-content' }}
    rowKey="id"
    size="small"
    columns={columns}

