import { PageError } from '../components/feedback/PageError';

/** The four severity tiers that count as "evaluated" (ADR 0005) — skip/error don't. */
const SEVERITY_STATUSES = new Set<ResultStatus>(['pass', 'warn', 'fail', 'critical']);

