() => new Promise(res => {
  const tab = [...document.querySelectorAll('.ant-tabs-tab')].find(t => t.textContent.includes('Pipeline runs'));
  tab.click();
  setTimeout(() => {
    const row = [...document.querySelectorAll('tr.ant-table-row')].find(r => r.innerText.includes('zz_local_1282_verify'));
    if (!row) return res('row not found');
    const tbl = row.closest('table');
    const headers = [...tbl.querySelectorAll('th')].map(th => th.innerText.trim());
    const fr = row.children[headers.indexOf('Failure reason')];
    const inner = fr.querySelector('span');
    const pr = row.children[headers.indexOf('Provider run')];
    const prInner = pr.querySelector('code span, span[style]');
    res({
      failureReason: {
        cellW: Math.round(fr.getBoundingClientRect().width),
        innerW: Math.round(inner.getBoundingClientRect().width),
        scrollW: inner.scrollWidth,
        clipped: inner.scrollWidth > Math.ceil(inner.clientWidth),
      },
      providerRun: prInner ? {
        innerW: Math.round(prInner.getBoundingClientRect().width),
        clipped: prInner.scrollWidth > Math.ceil(prInner.clientWidth),
        copyButtonVisible: !!pr.querySelector('.ant-typography-copy'),
      } : 'not found',
      tableW: Math.round(tbl.getBoundingClientRect().width),
      viewportW: window.innerWidth,
    });
  }, 1200);
})

