  const i = headers.indexOf('Provider run');
  const rows = [...tbl.querySelectorAll('tr.ant-table-row')];
  const measured = rows.map(r => {
    const s = r.children[i]?.querySelector('span[style*="max-width"]');
    return s ? { text: s.innerText.slice(0,26), innerW: Math.round(s.getBoundingClientRect().width), contentW: s.scrollWidth, clipped: s.scrollWidth > Math.ceil(s.clientWidth) } : null;
  }).filter(Boolean).sort((a,b)=>b.contentW-a.contentW);
  return { rowCount: rows.length, boundedCells: measured.length, longest: measured.slice(0,2) };
}

