async (page) => {
  await page.getByRole('tab', { name: 'Pipeline runs' }).click();
  await page.waitForTimeout(2500);

  const out = await page.evaluate(() => {
    const tbl = [...document.querySelectorAll('.ant-table table')]
      .find(t => [...t.querySelectorAll('th')].some(th => th.innerText.trim() === 'Failure reason'));
    if (!tbl) return { error: 'no pipeline table' };
    const headers = [...tbl.querySelectorAll('th')].map(th => th.innerText.trim());
    const fi = headers.indexOf('Failure reason');
    const pi = headers.indexOf('Provider run');
    const rows = [...tbl.querySelectorAll('tr.ant-table-row')];

    const measure = (idx) => rows.map(r => {
      const s = r.children[idx]?.querySelector('span[style*="max-width"]');
      return s ? { w: Math.round(s.getBoundingClientRect().width), content: s.scrollWidth,
                   clipped: s.scrollWidth > Math.ceil(s.clientWidth), text: s.innerText.slice(0, 45) } : null;
    }).filter(Boolean).sort((a, b) => b.content - a.content);

    const fr = measure(fi), pr = measure(pi);
    return {
      rows: rows.length,
      failureReason: { boundedCells: fr.length, widest: fr[0] ?? null },
      providerRun: { boundedCells: pr.length, widest: pr[0] ?? null },
      tableWidth: Math.round(tbl.getBoundingClientRect().width),
      viewportWidth: window.innerWidth,
      horizontalScrollbarLength: (() => {
        const w = tbl.closest('.ant-table-content, .ant-table-body');
        return w ? { scrollWidth: w.scrollWidth, clientWidth: w.clientWidth } : null;
      })(),
    };
  });
  return JSON.stringify(out, null, 2);
}

