    const scope = document.querySelector('[data-testid="rd-screen"]') || document;
    const tbl = [...scope.querySelectorAll('.ant-table table')]
      .find(t => [...t.querySelectorAll('th')].some(th => th.innerText.trim() === 'Observed'));
    if (!tbl) return { error: 'no observed table' };
    const headers = [...tbl.querySelectorAll('th')].map(th => th.innerText.trim());
    const oi = headers.indexOf('Observed');
    const cells = [...tbl.querySelectorAll('tr.ant-table-row')].map(r => {
      const s = r.children[oi]?.querySelector('span[style*="max-width"]');
      return s ? { w: Math.round(s.getBoundingClientRect().width), content: s.scrollWidth,
                   clipped: s.scrollWidth > Math.ceil(s.clientWidth), text: s.innerText.slice(0, 50) } : null;
    }).filter(Boolean).sort((a, b) => b.content - a.content);
    return {
      url: location.pathname,
      suite: document.querySelector('h3')?.innerText,
      boundedCells: cells.length,
      widest: cells.slice(0, 2),
      tableWidth: Math.round(tbl.getBoundingClientRect().width),
    };
  });
  return JSON.stringify(out, null, 2);
}

